select id
from collect_interface_config
where id = #{interfaceId}
  and task_id = #{taskId}
for update

select collection_count
from collect_interface_statistics
where task_id = #{taskId}
  and interface_id = #{interfaceId}
  and statistics_time = #{statisticsTime}

mapper.update:
update collect_interface_config
set data_packet_count = coalesce(data_packet_count, 0) + #{increment}
where id = #{interfaceId}
  and task_id = #{taskId}
